const trackedTweets = $("Fetch Tracked Account Tweets").all().map(item => item.json);
const trendingTweets = $("Fetch Trending AI Tweets").all().map(item => item.json);
const newsStories = $("Fetch AI News Stories").all().map(item => item.json);

const cleanTweets = (tweets) => tweets
  .filter(t => !t.isReply)
  .slice(0, 10)
  .map(t => ({
    text: t.fullText || t.text,
    author: t.author?.name || "Unknown",
    handle: t.author?.userName || "",
    url: t.url || ""
  }));

const cleanNews = (stories) => stories.slice(0, 10).map(s => ({
  title: s.title || "",
  source: s.source || "",
  description: s.description || "",
  url: (s.url || "").split("?")[0]
}));

const output = {
  trackedAccountPosts: cleanTweets(trackedTweets),
  trendingAIPosts: cleanTweets(trendingTweets),
  newsStories: cleanNews(newsStories)
};

return [{ json: output }];

function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const data = $input.first().json;
const reportId = uuidv4();
const generatedAt = new Date().toISOString();

const trackedAccountPosts = (data.trackedAccountPosts || []).map((p, i) => ({
  id: "tap-" + (i + 1),
  ...p
}));

const trendingAIPosts = (data.trendingAIPosts || []).map((p, i) => ({
  id: "trp-" + (i + 1),
  ...p
}));

const newsStories = (data.newsStories || []).map((s, i) => ({
  id: "ns-" + (i + 1),
  ...s
}));

return [{
  json: {
    report_id: reportId,
    generated_at: generatedAt,
    trackedAccountPosts,
    trendingAIPosts,
    newsStories
  }
}];

function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function sqlEscape(s) {
  return String(s == null ? "" : s).replace(/'/g, "''");
}

const raw = $input.first().json.content[0].text;
const clean = raw.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error("Claude did not return valid JSON. First 500 chars: " + clean.substring(0, 500));
}

if (!parsed.ideas || !Array.isArray(parsed.ideas)) {
  throw new Error("Claude response missing ideas array.");
}

const sourceData = $("Tag Sources With IDs").first().json;
const reportId = sourceData.report_id;
const generatedAt = sourceData.generated_at;

const ideas = parsed.ideas.map((idea, i) => ({
  id: uuidv4(),
  report_id: reportId,
  rank: idea.rank || (i + 1),
  hook: idea.hook || "",
  angle: idea.angle || "",
  why_it_works: idea.why_it_works || "",
  source_type: idea.source_type || "news_story",
  source_ref_id: idea.source_ref_id || "",
  source_url: idea.source_url || "",
  source_text: idea.source_text || "",
  source_author: idea.source_author || "",
  generated_at: generatedAt
}));

const reportPayload = {
  report_id: reportId,
  generated_at: generatedAt,
  trackedAccountPosts: sourceData.trackedAccountPosts,
  trendingAIPosts: sourceData.trendingAIPosts,
  newsStories: sourceData.newsStories,
  ideas
};

const reportPayloadLiteral = "'" + sqlEscape(JSON.stringify(reportPayload)) + "'::jsonb";

const valuesRows = ideas.map(idea => {
  const cols = [
    "'" + sqlEscape(idea.id) + "'::uuid",
    "'" + sqlEscape(idea.report_id) + "'::uuid",
    String(idea.rank),
    "'" + sqlEscape(idea.hook) + "'",
    "'" + sqlEscape(idea.angle) + "'",
    "'" + sqlEscape(idea.why_it_works) + "'",
    "'" + sqlEscape(idea.source_type) + "'",
    "'" + sqlEscape(idea.source_ref_id) + "'",
    "'" + sqlEscape(idea.source_url) + "'",
    "'" + sqlEscape(idea.source_text) + "'",
    "'" + sqlEscape(idea.source_author) + "'",
    reportPayloadLiteral,
    "'" + sqlEscape(generatedAt) + "'::timestamptz",
    "'draft'"
  ];
  return "(" + cols.join(", ") + ")";
}).join(",\n");

const insertSql = "INSERT INTO public.newsjacking_ideas (id, report_id, rank, hook, angle, why_it_works, source_type, source_ref_id, source_url, source_text, source_author, report_payload, generated_at, status) VALUES \n" + valuesRows + ";";

return [{
  json: {
    report_id: reportId,
    generated_at: generatedAt,
    trackedAccountPosts: sourceData.trackedAccountPosts,
    trendingAIPosts: sourceData.trendingAIPosts,
    newsStories: sourceData.newsStories,
    ideas,
    insert_sql: insertSql
  }
}];

const data = $("Parse Claude JSON").first().json;

const esc = (s) => String(s == null ? "" : s)
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;")
  .replace(/'/g, "&#39;");

const postCard = (p) => `<div style="background: #f8f9fa; border-radius: 8px; padding: 16px; margin-bottom: 12px;">
  <p style="font-weight: 600; font-size: 14px; margin: 0 0 4px;"><a href="${esc(p.url)}" target="_blank" style="color: #1a1a1a; text-decoration: none;">${esc(p.author)}</a> <span style="color: #666; font-weight: 400;">@${esc(p.handle)}</span></p>
  <p style="margin: 0; font-size: 14px;">${esc(p.text)}</p>
  <a href="${esc(p.url)}" target="_blank" style="font-size: 12px; color: #0A66C2; text-decoration: none; margin-top: 8px; display: inline-block;">View post \u2192</a>
</div>`;

const newsCard = (s) => `<div style="background: #f8f9fa; border-radius: 8px; padding: 16px; margin-bottom: 12px;">
  <a href="${esc(s.url)}" target="_blank" style="font-weight: 700; font-size: 15px; margin: 0 0 4px; color: #1a1a1a; text-decoration: none; display: block;">${esc(s.title)}</a>
  <p style="font-size: 12px; color: #0A66C2; text-transform: uppercase; letter-spacing: 0.5px; margin: 0 0 8px;">${esc(s.source)}</p>
  <p style="margin: 0; font-size: 14px; color: #444;">${esc(s.description)}</p>
  <a href="${esc(s.url)}" target="_blank" style="font-size: 12px; color: #0A66C2; text-decoration: none; margin-top: 8px; display: inline-block;">Read article \u2192</a>
</div>`;

const ideaCard = (idea) => {
  return `<div style="background: #f8f9fa; border-radius: 8px; padding: 20px; margin-bottom: 16px; border-left: 4px solid #0A66C2;">
    <p style="font-size: 12px; color: #0A66C2; text-transform: uppercase; letter-spacing: 0.5px; margin: 0 0 8px;">Idea #${idea.rank} | Source: ${esc(idea.source_author)}</p>
    <p style="font-size: 17px; font-weight: 700; margin: 0 0 12px; line-height: 1.4;">${esc(idea.hook)}</p>
    <p style="font-size: 14px; margin: 0 0 8px;"><strong>Angle:</strong> ${esc(idea.angle)}</p>
    <p style="font-size: 13px; color: #666; margin: 0 0 8px;"><strong>Why it works:</strong> ${esc(idea.why_it_works)}</p>
    <p style="font-size: 11px; color: #999; margin: 0; font-family: monospace;">id: ${esc(idea.id)}</p>
  </div>`;
};

const section = (title, body) => `<div style="border-top: 3px solid #0A66C2; padding-top: 24px; margin-bottom: 32px;">
  <h2 style="font-size: 18px; text-transform: uppercase; letter-spacing: 1px; color: #0A66C2; margin-bottom: 16px;">${title}</h2>
  ${body}
</div>`;

const html = `<div style="font-family: \u0027Helvetica Neue\u0027, Arial, sans-serif; max-width: 640px; margin: 0 auto; color: #1a1a1a; line-height: 1.6;">
  <div style="text-align: center; padding: 32px 0 24px;">
    <h1 style="font-size: 28px; font-weight: 700; margin: 0;">Your Daily AI Newsjacking Report</h1>
    <p style="color: #666; font-size: 14px; margin: 8px 0 0;">Fresh post ideas based on what is trending right now</p>
  </div>
  ${section("Tracked Account Posts", (data.trackedAccountPosts || []).map(postCard).join(""))}
  ${section("Trending AI Posts", (data.trendingAIPosts || []).map(postCard).join(""))}
  ${section("Top News Stories", (data.newsStories || []).map(newsCard).join(""))}
  ${section("10 LinkedIn Post Ideas", (data.ideas || []).map(ideaCard).join(""))}
  <div style="text-align: center; padding: 24px 0; border-top: 1px solid #e0e0e0; color: #999; font-size: 12px;">
    Generated by your AI Newsjacking Workflow
  </div>
</div>`;

return [{ json: { html, ideas: data.ideas, trackedAccountPosts: data.trackedAccountPosts, trendingAIPosts: data.trendingAIPosts, newsStories: data.newsStories } }];

const data = $("Parse Claude JSON").first().json;

let msg = "*Your Daily AI Newsjacking Report*\nFresh post ideas based on what is trending right now\n\n";

const sectionDivider = (title) => `\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n*${title}*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n`;

msg += sectionDivider("Tracked Account Posts");
for (const p of (data.trackedAccountPosts || [])) {
  msg += `<${p.url}|${p.author}> @${p.handle}\n${p.text}\n\n`;
}

msg += sectionDivider("Trending AI Posts");
for (const p of (data.trendingAIPosts || [])) {
  msg += `<${p.url}|${p.author}> @${p.handle}\n${p.text}\n\n`;
}

msg += sectionDivider("Top News Stories");
for (const s of (data.newsStories || [])) {
  msg += `<${s.url}|${s.title}>\n_${s.source}_\n${s.description}\n\n`;
}

msg += sectionDivider("10 LinkedIn Post Ideas");
for (const idea of (data.ideas || [])) {
  msg += `*Idea #${idea.rank}* | Source: ${idea.source_author}\n*${idea.hook}*\n>_Angle:_ ${idea.angle}\n>_Why it works:_ ${idea.why_it_works}\n_id: ${idea.id}_\n\n`;
}

msg += "_Generated by your AI Newsjacking Workflow_";

return [{ json: { slackMessage: msg } }];
